@router.put("/tenants/{tenant_id}/flags/{flag_key}/kill-switch")
async def toggle_tenant_feature_kill_switch(
    tenant_id: str,
    flag_key: str,
    payload: KillSwitchPayload,
    current_user: User = Depends(get_current_user)
):
    if current_user.tenant_id != tenant_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: administrative privileges required for target tenant")

    await flag_admin_client.set_tenant_override(
        tenant_id=tenant_id,
        flag_key=flag_key,
        enabled=payload.enabled
    )
    return {"status": "kill_switch_updated", "tenant_id": tenant_id, "flag": flag_key, "enabled": payload.enabled}
